// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createCollection, createLink, createHighlight, deleteLink, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const collectionsPostRequestBody: string = `{
        "name": "Highlights Post Colours"
    }`;

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "id": 711
        },
        "name": "Highlights Post Source",
        "tags": [],
        "type": "url",
        "url": "https://example.com/hl-post"
    }`;

    // Request Body
    const highlightsPostRequestBody: string = `{
        "color": "blue",
        "comment": "supported",
        "endOffset": 24,
        "linkId": 722,
        "startOffset": 0,
        "text": "Supported colour passage"
    }`;

    // Request Body
    const highlightsPost1RequestBody: string = `{
        "color": "purple",
        "comment": "unsupported",
        "endOffset": 56,
        "linkId": 722,
        "startOffset": 30,
        "text": "Unsupported colour passage"
    }`;

    // Request Body
    const highlightsPost2RequestBody: string = `{
        "color": "",
        "comment": "empty",
        "endOffset": 80,
        "linkId": 722,
        "startOffset": 60,
        "text": "Empty colour passage"
    }`;

    const collectionsPostResponse = await createCollection(client, URL_localhost, headers, collectionsPostRequestBody);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    const linksPostResponse = await createLink(client, URL_localhost, headers, linksPostRequestBody, {"collection.id": getResponseValue(collectionsPostResponse, "response.id")});
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    const linkId = getResponseValue(linksPostResponse, "response.id");
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'collection name').toBe("Highlights Post Colours");
    expect(getResponseValue(linksPostResponse, "response.name"), 'link name').toBe("Highlights Post Source");
    expect(getResponseValue(linksPostResponse, "response.url"), 'link url').toBe("https://example.com/hl-post");

    const highlightsPostResponse = await createHighlight(client, URL_localhost, headers, highlightsPostRequestBody, {"linkId": linkId});
    expect(highlightsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsPostResponse, "response.color"), 'a supported colour is stored').toBe("blue");
    expect(getResponseValue(highlightsPostResponse, "response.text"), 'stored text').toBe("Supported colour passage");
    expect(getResponseValue(highlightsPostResponse, "response.comment"), 'stored comment').toBe("supported");
    expect(getResponseValue(highlightsPostResponse, "response.linkId"), 'stored against the link').toBe(linkId);

    const highlightsPost1Response = await createHighlight(client, URL_localhost, headers, highlightsPost1RequestBody, {"linkId": linkId}, 400);
    expect(highlightsPost1Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsPost1Response, "response"), 'a colour outside the four is refused').toBe("Error: Invalid option: expected one of \"yellow\"|\"green\"|\"blue\"|\"red\" [color]");

    const highlightsPost2Response = await createHighlight(client, URL_localhost, headers, highlightsPost2RequestBody, {"linkId": linkId}, 400);
    expect(highlightsPost2Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsPost2Response, "response"), 'an empty colour is refused').toBe("Error: Invalid option: expected one of \"yellow\"|\"green\"|\"blue\"|\"red\" [color]");

    const linksLinksDeleteResponse = await deleteLink(client, URL_localhost, headers, linkId);
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted link').toBe(linkId);
    const collectionsCollectionsDeleteResponse = await deleteCollection(client, URL_localhost, headers, getResponseValue(collectionsPostResponse, "response.id"));
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
});
